// Rung <= 1.01GB: partition complete finite phrases by sampled lexical splitters.
// Sampling affects balance only. Oversize buckets refuse before exceeding a cap.
#include <algorithm>
#include <cassert>
#include <cstdint>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <string>
#include <string_view>
#include <vector>
#include <fcntl.h>
#include <sys/mman.h>
#include <unistd.h>
using namespace std;namespace fs=std::filesystem;using U=uint32_t;using Q=uint64_t;using K=pair<string_view,bool>;
struct Rec{U p,h,j;}; struct Assign{U j,id;};struct Word{U p,h;};static_assert(sizeof(Rec)==12 && sizeof(Assign)==8 && sizeof(Word)==8);
U common(string_view a,string_view b){U h=0;while(h<a.size()&&h<b.size()&&a[h]==b[h])++h;return h;}
Q io(){ifstream f("/proc/self/io");string k;Q v;while(f>>k>>v)if(k=="read_bytes:")return v;abort();}
int main(int ac,char**av){assert(ac==3);U n=fs::file_size(av[1]);assert(n && fs::file_size(av[1])==n && n<=1010000000);fs::path d=av[2];assert(fs::create_directory(d));int fd=open(av[1],O_RDONLY);assert(fd>=0);const char*t=(char*)mmap(nullptr,n,PROT_READ,MAP_PRIVATE,fd,0);assert(t!=MAP_FAILED);madvise((void*)t,n,MADV_SEQUENTIAL);Q live=0,peak=0;auto add=[&](Q v){live+=v;assert(live<=2ull*n);peak=max(peak,live);};auto rm=[&](fs::path p){live-=fs::file_size(p);assert(fs::remove(p));};auto guard=[&](){assert(io()<=6ull*n);};auto scan=[&](auto visit){U s=0,j=0;for(U i=1;i+8<=n;i++){if(!(i%1048576))guard();Q h=1469598103934665603ull;for(int a=0;a<8;a++)h=(h^(unsigned char)t[i+a])*1099511628211ull;if(h%31==0){visit(Rec{s,i+8-s,j++});s=i;}}visit(Rec{s,(n-s)|0x80000000u,j++});return j;};auto key=[&](Rec r)->K{return {{t+r.p,r.h&0x7fffffffu},bool(r.h>>31)};};
 vector<pair<string,bool>>sample;Q next=0,sz=0;scan([&](Rec r){if(r.p>=next){auto k=key(r);sz+=k.first.size();assert(sz<16<<20);sample.emplace_back(k.first,k.second);next=r.p+max(1u,n/32768);}});sort(sample.begin(),sample.end());vector<K> piv;for(int b=1;b<256;b++)piv.push_back({sample[sample.size()*b/256].first,sample[sample.size()*b/256].second});
 auto path=[&](char c,int i){return d/(string(1,c)+to_string(i));};vector<ofstream> out(256);vector<U> sizes(256),cnt(256);for(int b=0;b<256;b++)out[b].open(path('b',b),ios::binary);U m=scan([&](Rec r){auto k=key(r);int b=lower_bound(piv.begin(),piv.end(),k)-piv.begin();U len=k.first.size();add(12ull+len);sizes[b]+=12+len;assert(sizes[b]<=64<<20 && ++cnt[b]<=2000000);out[b].write((char*)&r,12).write(k.first.data(),len);assert(out[b]);});for(auto &f:out){f.close();assert(f);}piv.clear();sample.clear();
 const U shard=1<<18;vector<ofstream> ass((m+shard-1)/shard);for(U i=0;i<ass.size();i++)ass[i].open(path('a',i),ios::binary);ofstream dict(d/"dictionary.refs",ios::binary),adj(d/"dict-adj.u32",ios::binary);string boundary;U words=0;Q desc=0;for(int b=0;b<256;b++){guard();vector<char>data(sizes[b]);ifstream f(path('b',b),ios::binary);assert(f.read(data.data(),data.size()));f.close();rm(path('b',b));vector<U> offsets;offsets.reserve(cnt[b]);auto rec=[&](U i){Rec r;__builtin_memcpy(&r,data.data()+i,12);return r;};auto local=[&](U i)->K{auto r=rec(i);return {{data.data()+i+12,r.h&0x7fffffffu},bool(r.h>>31)};};for(U i=0;i<data.size();){offsets.push_back(i);i+=12+local(i).first.size();}assert(offsets.size()==cnt[b]);sort(offsets.begin(),offsets.end(),[&](U a,U b){return local(a)<local(b);});K last;bool first=true;for(U i:offsets){Rec r=rec(i);auto k=local(i);if(first||last!=k){add(12);U h=common(first?string_view(boundary):last.first,k.first);adj.write((char*)&h,4);assert(adj);Word w{r.p,r.h};dict.write((char*)&w,8);assert(dict);words++;desc+=k.first.size()-(k.second?0:8);last=k;first=false;}Assign a{r.j,words-1};add(8);ass[r.j/shard].write((char*)&a,8);assert(ass[r.j/shard]);}if(!first)boundary=last.first;}
 adj.close();assert(adj);dict.close();assert(dict);for(auto &f:ass){f.close();assert(f);}ofstream parse(d/"parse.u32",ios::binary);for(U i=0;i<ass.size();i++){guard();U rows=min(shard,m-i*shard);vector<U> block(rows,UINT32_MAX);ifstream f(path('a',i),ios::binary);Assign a;for(U z=0;z<rows;z++){assert(f.read((char*)&a,8)&&a.j/shard==i&&a.j%shard<rows&&block[a.j%shard]==UINT32_MAX);block[a.j%shard]=a.id;}assert(f.peek()==EOF);f.close();rm(path('a',i));add(rows*4ull);parse.write((char*)block.data(),rows*4);assert(parse);}parse.close();assert(parse);
 // Independent exact validation on sandbox: dictionary strictly sorted; decode every parse row.
 if(n<=101000000){vector<Word>w(words);ifstream df(d/"dictionary.refs",ios::binary);assert(df.read((char*)w.data(),words*8ull));auto dk=[&](U id){auto v=w.at(id);return key(Rec{v.p,v.h,0});};ifstream af(d/"dict-adj.u32",ios::binary);for(U i=0;i<words;i++){U h;assert(af.read((char*)&h,4));if(i){assert(dk(i-1)<dk(i));assert(common(dk(i-1).first,dk(i).first)==h);}else assert(h==0);}assert(af.peek()==EOF);ifstream pf(d/"parse.u32",ios::binary);assert(scan([&](Rec r){U id;assert(pf.read((char*)&id,4)&&dk(id)==key(r));})==m);assert(pf.peek()==EOF);}guard();printf("LEXPARSE n=%u phrases=%u distinct=%u descriptors=%llu max_bucket=%u peak_counted=%llu final_columns=%llu reads=%llu decode_verified=%d\n",n,m,words,(unsigned long long)desc,*max_element(sizes.begin(),sizes.end()),(unsigned long long)peak,(unsigned long long)live,(unsigned long long)io(),int(n<=101000000));}
